// Two decoders overlap the tail after 6 s with the next clip's first frames.
class HeroVideoController {
  constructor(videos, options={}) {
    this.videos=videos;this.options=options;this.front=0;this.phase='idle';
    this.running=false;this.destroyed=false;this.raf=null;this.token=0;
    this.brandRevealed=Boolean(options.brandRevealed);
    videos.forEach(v=>{v.muted=true;v.loop=false;v.playsInline=true;v.style.opacity='1';});
    this.paint();
  }
  paint(){this.videos.forEach((v,i)=>v.style.zIndex=i===this.front?'2':'1');}
  revealBrand(duration){if(!this.brandRevealed){this.brandRevealed=true;this.options.onBrandReveal?.(duration);}}
  async resume(){
    if(this.destroyed||this.running)return;this.running=true;const token=++this.token;
    try{
      if(this.phase==='fading')await Promise.all(this.videos.map(v=>v.play()));
      else await this.videos[this.front].play();
      if(!this.running||this.destroyed||token!==this.token){if(!this.running)this.videos.forEach(v=>v.pause());return;}
      this.options.onPlaying?.();this.schedule();
    }catch(error){if(token===this.token){this.running=false;this.options.onBlocked?.(error);}}
  }
  pause(){this.running=false;++this.token;cancelAnimationFrame(this.raf);this.raf=null;this.videos.forEach(v=>v.pause());}
  schedule(){if(this.running&&!this.destroyed&&this.raf===null)this.raf=requestAnimationFrame(()=>{this.raf=null;this.step();this.schedule();});}
  async startNext(){
    if(this.phase!=='idle'||!this.running||this.destroyed)return;
    const next=this.videos[1-this.front];this.phase='starting';next.currentTime=0;next.style.opacity='1';
    const token=this.token;
    try{
      await next.play();
      if(this.destroyed||!this.running||token!==this.token){next.pause();if(!this.destroyed)this.phase='idle';return;}
      this.phase='fading';
    }catch(error){this.phase='idle';this.pause();this.options.onBlocked?.(error);}
  }
  step(){
    if(this.destroyed||!this.running)return;
    const front=this.videos[this.front],duration=front.duration;
    if(!Number.isFinite(duration)||duration<=0)return;
    const fadeStart=Math.min(6,Math.max(0,duration-.3));
    const fadeDuration=Math.max(.05,duration-fadeStart);
    if(front.currentTime>=fadeStart){
      this.revealBrand(fadeDuration);
      if(this.phase==='idle')this.startNext();
    }
    if(this.phase==='fading'){
      const alpha=Math.max(0,Math.min(1,(front.currentTime-fadeStart)/fadeDuration));
      front.style.opacity=String(1-alpha);
      // Keep the incoming decoder at its current time: do not restart it here.
      if(alpha>=.995||front.ended){
        const outgoing=this.front;this.front=1-this.front;this.phase='idle';
        this.paint();this.videos[this.front].style.opacity='1';
        this.videos[outgoing].pause();this.videos[outgoing].style.opacity='1';this.videos[outgoing].currentTime=0;
        this.options.onLoop?.();
      }
    }
  }
  destroy(){this.pause();this.destroyed=true;}
}

