function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;}
function img(name,alt='',cls='',loading='lazy'){return `<img src="${ASSETS[name]}" alt="${escape(alt)}" ${cls?`class="${cls}"`:''} loading="${loading}" decoding="async">`;}
function link(page,label,cls='',extra=''){return `<a href="#/${page}" ${cls?`class="${cls}"`:''} ${extra}>${label}</a>`;}
function external(url,label,cls=''){return `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer" ${cls?`class="${cls}"`:''}>${label}</a>`;}
const DOWNLOAD_CHANNELS=[['apple','App Store'],['google','Google Play'],['apk','APK'],['xiaomi','Xiaomi'],['oppo','OPPO'],['vivo','vivo'],['huawei','HUAWEI AppGallery']];
function downloadCopy(){return {hi:{more:'और डाउनलोड विकल्प',title:'और डाउनलोड विकल्प',all:'डाउनलोड का माध्यम चुनें',note:'Google Play उपलब्ध है। अन्य लिंक की पुष्टि बाकी है।'},zh:{more:'更多下载渠道',title:'更多下载渠道',all:'选择下载渠道',note:'Google Play 已接通，其他渠道待核实。'},en:{more:'More download options',title:'More download options',all:'Choose a download channel',note:'Google Play is available. Other links await verification.'},id:{more:'Pilihan unduhan lain',title:'Pilihan unduhan lain',all:'Pilih kanal unduhan',note:'Google Play tersedia. Tautan lain belum terverifikasi.'}}[lang];}
function channelBadge(key){const name=DOWNLOAD_CHANNELS.find(item=>item[0]===key)[1];return `<button type="button" class="download-badge" data-channel="${key}" data-action="preview-download" aria-label="${escape(name)}">${img('download-'+key+'.png',name,'','eager')}</button>`;}
function stores(){return `<div class="download-module"><div class="primary-downloads">${DOWNLOAD_CHANNELS.slice(0,3).map(([key])=>channelBadge(key)).join('')}</div><button type="button" class="more-downloads" data-action="more-downloads" aria-expanded="false" aria-controls="more-download-panel">${downloadCopy().more}<svg class="more-downloads-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button></div>`;}
function showMoreDownloads(trigger){
 openDialog(`<div class="dialog-title"><h2 id="dialog-heading">${downloadCopy().title}</h2>${closeButton()}</div><div class="secondary-downloads">${DOWNLOAD_CHANNELS.slice(3).map(([key])=>channelBadge(key)).join('')}</div>`);
 const backdrop=$('.dialog-backdrop'),panel=$('.modal-shell');backdrop.classList.add('channels-backdrop');panel.classList.add('channel-panel');panel.id='more-download-panel';trigger.setAttribute('aria-expanded','true');
 if(window.innerWidth>680){const r=trigger.getBoundingClientRect(),p=panel.getBoundingClientRect();panel.style.left=Math.max(12,Math.min(r.left,window.innerWidth-p.width-12))+'px';panel.style.top=Math.max(12,r.bottom+10+p.height<=window.innerHeight?r.bottom+10:r.top-p.height-10)+'px';}
}
function setMobileMenu(open){
 const menu=$('#mobile-nav'),toggle=$('#menu-toggle');if(!menu||!toggle)return;
 menu.classList.toggle('open',open);document.body.classList.toggle('mobile-menu-open',open);
 toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');toggle.innerHTML=icon(open?'close':'menu');
 $('#main-content').inert=open;$('#site-footer').inert=open;scheduleHomeAdvance();
}
function renderHeader(){const t=data();$('#site-header').innerHTML=`<div class="wrap header-inner">${link('home',img('brand-logo','Bangbo','','eager'),'brand','aria-label="Bangbo Home"')}<nav class="desktop-nav" aria-label="Main navigation">${['home','about','help','contact'].map(p=>link(p,escape(t.nav[p]),activePage===p?'active':'',activePage===p?'aria-current="page"':'')).join('')}</nav><div class="header-tools">${external(LINKS.recharge,icon('wallet')+escape(t.nav.recharge),'recharge')}<select class="language" id="language" aria-label="Website language"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="id" ${lang==='id'?'selected':''}>Indonesia</option><option value="hi" ${lang==='hi'?'selected':''}>हिन्दी</option><option value="zh" ${lang==='zh'?'selected':''}>中文 · 评审</option></select>${link('home?section=download',escape(t.nav.download)+icon('download'),'button header-download')}<button class="menu-button" id="menu-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open navigation">${icon('menu')}</button></div></div><nav class="mobile-nav" id="mobile-nav" aria-label="Mobile navigation"><div class="mobile-nav-content">${['home','about','help','contact','safety'].map(p=>link(p,escape(t.nav[p]),activePage===p?'active':'')).join('')}<div class="mobile-legal"><strong>${t.nav.safety}</strong>${['terms','privacy','children','community','bullying','cookies','law'].map(k=>link(k==='law'?'law-enforcement':'policy/'+k,t.footer[k])).join('')}<button type="button" data-action="cookies">${t.footer.settings}</button><small>${t.footer.copyright}</small></div></div><div class="mobile-menu-downloads" role="region" aria-label="${escape(t.nav.download)}">${stores()}</div></nav>`;}
function companyCopy(){return {"en":{"label":"App information"},"zh":{"label":"App 主体信息"},"id":{"label":"Informasi aplikasi"},"hi":{"label":"ऐप की जानकारी"}}[lang];}
function companyIdentity(){const c=companyCopy();return `<section class="app-identity inner-app-identity" aria-label="${c.label}"><p class="entity-name">Woola Singapore Pte. Ltd.</p><p class="entity-address">9 Straits View, #06-07, Marina One West Tower, Singapore 018937</p></section>`;}
function legalFooterLinks(){const t=data(),f=t.footer;return `<nav class="footer-links" aria-label="Footer">${['terms','privacy','children'].map(k=>link('policy/'+k,escape(f[k]))).join('')}${link('safety',escape(t.nav.safety))}${link('help',escape(t.nav.help))}<button type="button" data-action="cookies">${escape(f.settings)}</button></nav>`;}
function renderFooter(){const t=data(),f=t.footer;if(activePage==='home'){$('#site-footer').innerHTML=`${companyIdentity()}<div class="wrap compact-footer"><span>${f.copyright}</span>${legalFooterLinks()}</div><div id="download-dock-slot"><div id="mobile-home-downloads" role="region" aria-label="${t.nav.download}">${stores()}</div></div>`;return;}$('#site-footer').innerHTML=`<div class="wrap"><div class="footer-grid"><div class="footer-brand">${link('home',img('brand-logo','Bangbo'))}<p>${f.tagline}</p></div><div class="footer-col"><strong>${f.explore}</strong>${link('home',t.nav.home)}${link('about',t.nav.about)}${link('home?section=download',t.nav.download)}${external(LINKS.recharge,t.nav.recharge)}</div><div class="footer-col"><strong>${f.support}</strong>${link('help',t.nav.help)}${link('contact',t.nav.contact)}</div><div class="footer-col"><strong>${f.rules}</strong>${['terms','privacy','children','community','bullying','cookies','law'].map(k=>link(k==='law'?'law-enforcement':'policy/'+k,escape(f[k]))).join('')}</div></div>${companyIdentity()}<div class="footer-bottom"><span class="copyright">${f.copyright}</span>${legalFooterLinks()}</div></div>`;}
function sceneBackground(){return `<div class="scene-backdrop" aria-hidden="true"><i></i><svg viewBox="0 0 720 420" fill="none"><g stroke="var(--scene-line)" stroke-width="2" opacity=".35"><path d="M420 100q90-45 190 0v230q-100-45-190 0q-90-45-190 0V100q100-45 190 0zM420 100v230"/><path d="M260 145q65-22 125 0m-125 45q65-22 125 0m70-45q60-22 120 0m-120 45q60-22 120 0"/></g><path d="M555 80h40v95l-20-15-20 15z" fill="var(--scene-yellow)" opacity=".45"/></svg></div>`;}
function ambient(){return '<div class="ambient" aria-hidden="true"></div>';}
function heroVideoPlaceholder(){return `<div class="hero-media-video"><div class="hero-video-stage"><picture><source media="(max-width:680px)" srcset="assets/placeholder-hero-mobile.svg"><img class="hero-loop-freeze" src="assets/placeholder-hero-desktop.svg" alt="Bangbo media placeholder" loading="eager" decoding="async"></picture></div></div>`;}
function homePage(){const t=data(),h=t.home;return `<div class="home-stage" aria-roledescription="carousel" aria-label="Bangbo"><div class="home-window"><div class="home-deck"><section class="hero home-slide video-hero" id="hello"><div class="hero-background-layer">${img('p1_bg-105ed6b6c9.png','','hero-background-image','eager')}</div><div class="wrap hero-inner"><div class="hero-copy"><h1 class="hero-title">${h.title}</h1><p class="hero-description">${h.description}</p><div class="desktop-downloads">${stores()}</div></div><div class="hero-media">${heroVideoPlaceholder()}</div></div></section>${h.scenes.map((s,i)=>`<section class="home-slide scene social-scene ${i%2===1?'reverse ':''}${['phone-green','phone-peach','phone-mint'][i%3]}" id="${s.id}">${sceneBackground()}${ambient()}<div class="wrap scene-grid"><div class="scene-visual">${img(s.image,s.title+' — Bangbo','scene-artwork','eager')}</div><div class="scene-copy"><h2>${s.title}</h2><p>${s.description}</p><div class="desktop-downloads">${stores()}</div></div></div></section>`).join('')}</div></div><nav class="screen-nav" aria-label="Home sections">${[{id:'hello',title:t.nav.home,icon:'people'},...h.scenes].map((s,i)=>`<button data-slide="${i}" aria-label="${escape(s.title)}">${icon(s.icon)}<span>${s.title}</span></button>`).join('')}</nav><span class="sr-only" id="screen-status" aria-live="polite"></span></div>`;}
function fitMobileHome(force=false){
 const stage=$('.home-stage'),viewport=$('.home-window');if(!stage||!viewport||window.innerWidth>680)return;
 const key=[viewport.clientWidth,viewport.clientHeight,lang].join(':');if(!force&&key===homeFitKey)return;homeFitKey=key;
 const compact=viewport.clientHeight<350;stage.style.setProperty('--mobile-title-font',compact?'26px':'29px');stage.style.setProperty('--mobile-body-font',compact?'13px':'15px');
 for(const name of ['--copy-title','--copy-body','--home-copy-height'])stage.style.removeProperty(name);
 const maxima={title:0,body:0};
 $$('.home-slide:not(.loop-clone)').forEach(slide=>{const copy=$('.hero-copy,.scene-copy',slide);if(!copy)return;for(const [name,selector] of [['title','h1,h2'],['body','.hero-description,.scene-copy > p']]){const el=$(selector,copy);if(el)maxima[name]=Math.max(maxima[name],Math.ceil(el.getBoundingClientRect().height));}});
 for(const name of ['title','body'])stage.style.setProperty('--copy-'+name,maxima[name]+'px');
 stage.style.setProperty('--home-copy-height',(maxima.title+maxima.body+8)+'px');
}
function observeHomeLayout(){
 homeResizeObserver?.disconnect();homeResizeObserver=null;homeFitKey='';
 if(activePage!=='home')return;
 if(typeof ResizeObserver!=='undefined'){homeResizeObserver=new ResizeObserver(()=>fitMobileHome());homeResizeObserver.observe($('.home-window'));}
 requestAnimationFrame(()=>fitMobileHome(true));document.fonts?.ready.then(()=>fitMobileHome(true));
}
function updateVideoSize(){
 const frame=$('#hello .hero-media-video');if(!frame)return;const rect=frame.getBoundingClientRect();
 $$('.video-size').forEach(el=>el.textContent=`${Math.round(rect.width)} × ${Math.round(rect.height)} px`);
}
function playOpening(force=false){
 if(!force&&openingPlayed)return;openingPlayed=true;clearTimeout(openingTimer);document.body.classList.remove('opening');
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 void document.body.offsetHeight;document.body.classList.add('opening');openingTimer=setTimeout(()=>document.body.classList.remove('opening'),1400);
}
function prepareHomeLoop(){
 const deck=$('.home-deck');if(!deck||$('.loop-clone',deck))return;
 const originals=$$('.home-slide',deck);
 for(const [source,prepend] of [[originals.at(-1),true],[originals[0],false]]){
  const clone=source.cloneNode(true);clone.classList.add('loop-clone');clone.removeAttribute('id');$$('[id]',clone).forEach(el=>el.removeAttribute('id'));$$('h1',clone).forEach(el=>{const title=document.createElement('div');title.className=el.className+' hero-loop-title';title.innerHTML=el.innerHTML;el.replaceWith(title);});$$('video',clone).forEach(v=>v.remove());clone.inert=true;clone.setAttribute('aria-hidden','true');
  if(prepend)deck.prepend(clone);else deck.append(clone);
 }
 deck.addEventListener('transitionend',event=>{if(event.target===deck&&event.propertyName==='transform')settleLoop();});
}
function deckTransform(position){return window.innerWidth<=680?`translate3d(${-position*100}%,0,0)`:`translate3d(0,${-position*100}%,0)`;}
function settleLoop(){
 clearTimeout(loopTimer);loopTimer=null;const deck=$('.home-deck');if(!deck)return;
 if(deck.dataset.wrapping!=='true')return;deck.dataset.wrapping='false';deck.style.transition='none';deck.style.transform=deckTransform(homeSlide+1);void deck.offsetHeight;
 requestAnimationFrame(()=>{if(deck.isConnected)deck.style.transition='';});
}
function clearHomeAdvance(){clearTimeout(autoNextTimer);autoNextTimer=null;}
function autoAdvanceAllowed(){return !AUTO_ADVANCE_PAUSED&&activePage==='home'&&!document.hidden&&!$('#dialog-root').firstElementChild&&!$('#mobile-nav')?.classList.contains('open')&&!touchStart&&!(window.visualViewport?.scale>1.01);}
function scheduleHomeAdvance(){
 clearHomeAdvance();if(!autoAdvanceAllowed())return;
 if(homeSlide===0&&!homeVideoLapComplete)return;
 const videoSeconds=heroPlayer?.videos[0]?.duration;
 const fullScreenDuration=(Number.isFinite(videoSeconds)&&videoSeconds>0?videoSeconds:6.708333)*1000+1000;
 const slide=homeSlide,delay=slide===0?1000:fullScreenDuration;
 autoNextTimer=setTimeout(()=>{autoNextTimer=null;if(autoAdvanceAllowed()&&homeSlide===slide)setHomeSlide(slide+1,true);},delay);
}
function setHomeSlide(index,loop=false){
 clearHomeAdvance();clearTimeout(loopTimer);loopTimer=null;const previous=homeSlide;homeSlide=((index%screenTotal)+screenTotal)%screenTotal;if(homeSlide===0&&previous!==0){homeVideoLapComplete=false;disposeHeroVideo();}const deck=$('.home-deck');if(!deck)return;
 prepareHomeLoop();const wrap=loop&&(index<0||index>=screenTotal)&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
 deck.dataset.wrapping=String(wrap);deck.style.transition='';deck.style.transform=deckTransform(wrap?(index>=screenTotal?screenTotal+1:0):homeSlide+1);
 if(wrap)loopTimer=setTimeout(settleLoop,680);
 $$('.home-slide:not(.loop-clone)').forEach((el,i)=>{if(i!==homeSlide&&el.contains(document.activeElement))$('#main-content').focus({preventScroll:true});el.setAttribute('aria-hidden',String(i!==homeSlide));el.inert=i!==homeSlide;el.classList.toggle('is-active',i===homeSlide);});
 $$('[data-slide]').forEach((el,i)=>{el.classList.toggle('active',i===homeSlide);el.setAttribute('aria-current',i===homeSlide?'true':'false');});
 $('.home-stage').dataset.screen=String(homeSlide);requestAnimationFrame(()=>{updateVideoSize();fitMobileHome();const nav=$('.screen-nav'),selected=$('.screen-nav button.active');if(nav&&selected&&nav.scrollWidth>nav.clientWidth&&typeof nav.scrollTo==='function')nav.scrollTo({left:selected.offsetLeft-(nav.clientWidth-selected.offsetWidth)/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
 $('#screen-status').textContent=[data().nav.home,...data().home.scenes.map(s=>s.title)][homeSlide];
 syncHeroVideo();scheduleHomeAdvance();
}
function moveSlide(step){const now=Date.now();if(now-lastSlideAt<720)return;lastSlideAt=now;setHomeSlide(homeSlide+step,true);}
function disposeHeroVideo(){if(heroPlayer){heroPlayer.destroy();heroPlayer=null;}}
function freezeHeroLoopPreview(){
 if(!heroPlayer)return;const videos=heroPlayer.videos;if(!videos.some(v=>v.readyState>=2))return;
 $$('.loop-clone .hero-video-stage').forEach(stage=>{
  const canvas=document.createElement('canvas');canvas.className='hero-loop-freeze';canvas.width=videos[0].videoWidth;canvas.height=videos[0].videoHeight;
  if(!canvas.width||!canvas.height)return;const ctx=canvas.getContext('2d');if(!ctx)return;
  const order=[videos[1-heroPlayer.front],videos[heroPlayer.front]];for(const v of order){if(v.readyState>=2){ctx.globalAlpha=Number(v.style.opacity||1);ctx.drawImage(v,0,0,canvas.width,canvas.height);}}
  stage.replaceChildren(canvas);
 });
}
function syncHeroVideo(){
 const frame=$('#hello .hero-media-video');if(!frame){disposeHeroVideo();return;}
 const source=window.innerWidth<=680?(HERO_MEDIA.portrait||HERO_MEDIA.landscape):(HERO_MEDIA.landscape||HERO_MEDIA.portrait);
 const videos=$$('video',frame);if(videos.length!==2)return;
 if(!heroPlayer||heroPlayer.videos[0]!==videos[0]||heroPlayer.source!==source){
  disposeHeroVideo();videos.forEach(v=>{v.src=source;v.muted=true;v.load();});
  heroPlayer=new HeroVideoController(videos,{brandRevealed:heroBrandRevealed,onBrandReveal:duration=>{
   heroBrandRevealed=true;$$('.hero-brand-overlay').forEach(el=>{el.style.setProperty('--brand-fade-duration',duration+'s');el.classList.add('is-visible');});
  },onLoop:()=>{if(activePage==='home'&&homeSlide===0&&!homeVideoLapComplete){homeVideoLapComplete=true;scheduleHomeAdvance();}},onPlaying:()=>{frame.classList.add('has-video');$('.hero-play-fallback',frame).hidden=true;},onBlocked:()=>{$('.hero-play-fallback',frame).hidden=false;}});
  heroPlayer.source=source;
 }
 const active=activePage==='home'&&homeSlide===0&&!document.hidden;
 if(active&&(!matchMedia('(prefers-reduced-motion: reduce)').matches||heroUserStarted))heroPlayer.resume();
 else{freezeHeroLoopPreview();heroPlayer.pause();if(active)$('.hero-play-fallback',frame).hidden=false;}
}
function showDownload(){openDialog(`<div class="dialog-title"><h2 id="dialog-heading">${downloadCopy().all}</h2>${closeButton()}</div><div class="all-channel-grid">${DOWNLOAD_CHANNELS.map(([key])=>channelBadge(key)).join('')}</div>`);}
function downloadBand(){const h=data().home;return `<section class="download-band" id="download"><div class="wrap"><div><h2>${h.downloadTitle}</h2><p>${h.downloadText}</p></div><div>${stores()}</div></div></section>`;}
function intro(title,text,eyebrow){return `<section class="page-intro"><div class="wrap"><div class="breadcrumb">${link('home',data().nav.home)}<span>/</span><span>${data().nav[activePage]||data().nav.safety}</span></div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div></section>`;}
function aboutPage(){const a=data().about;return intro(a.title,a.intro,a.eyebrow)+`<section class="page-body"><div class="wrap"><div class="about-grid"><div class="about-copy"><h2>${a.heading}</h2>${a.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div><div class="about-art">${img('p1_youngs-38ed979a0c.png','Friends on Bangbo')}</div></div><div class="about-values">${a.values.map(([title,text],i)=>`<article>${icon(['people','live','shield'][i])}<h3>${title}</h3><p>${text}</p></article>`).join('')}</div></div></section>`+downloadBand();}
function helpPage(){const t=data(),h=t.help;return intro(h.title,h.intro,h.eyebrow).replace('</p></div></section>',`</p><div class="support-top"><div class="search-field">${icon('search')}<input id="faq-search" type="search" value="${escape(searchQuery)}" placeholder="${escape(h.placeholder)}" aria-label="${escape(h.placeholder)}"></div></div></div></section>`)+`<section class="page-body"><div class="wrap"><div class="support-layout"><aside class="support-tabs" aria-label="FAQ categories">${['all','account','payment','safety','download'].map((key,i)=>`<button data-category="${key}" class="${helpCategory===key?'active':''}" aria-pressed="${helpCategory===key}">${icon(['help','account','wallet','shield','download'][i])}${h[key]}</button>`).join('')}</aside><div><div class="faq-heading"><h2 id="faq-title">${h[helpCategory]}</h2><span id="faq-count" aria-live="polite"></span></div><div id="faq-results"></div><div class="support-contact"><div><h3>${h.more}</h3><p>${h.moreText}</p></div>${link('contact',h.contact+icon('arrow'),'button')}</div></div></div></div></section>`;}
function renderFaq(){const t=data(),q=searchQuery.trim().toLocaleLowerCase();const rows=t.faqs.filter(f=>(helpCategory==='all'||f[0]===helpCategory)&&(!q||(f[1]+' '+f[2]).toLocaleLowerCase().includes(q)));$('#faq-count').textContent=rows.length+' '+t.help.count;$('#faq-title').textContent=t.help[helpCategory];$('#faq-results').innerHTML=rows.length?rows.map(f=>`<details class="faq-item"><summary>${escape(f[1])}</summary><div class="faq-answer">${escape(f[2])}</div></details>`).join(''):`<p class="empty-state">${t.help.none}</p>`;const g=t.help.preparation;$('#faq-results').insertAdjacentHTML('beforeend',`<aside class="support-guide"><h3>${g.title}</h3><ul>${g[helpCategory].map(item=>`<li>${escape(item)}</li>`).join('')}</ul>${link('contact',t.nav.contact+icon('arrow'),'text-link')}</aside>`);} 
const policyKeys=['terms','privacy','children','community','bullying','cookies','law'];
function safetyPage(){const t=data(),s=t.safety;return intro(s.title,s.intro,s.eyebrow)+`<section class="page-body"><div class="wrap"><div class="safety-intro"><h2>${s.heading}</h2><p>${s.description}</p></div><div class="policy-list">${policyKeys.map((key,i)=>link(key==='law'?'law-enforcement':'policy/'+key,`<span class="policy-icon">${icon({terms:'file',privacy:'lock',children:'shield',community:'people',bullying:'heart',cookies:'cookie',law:'law'}[key])}</span><div><h3>${t.footer[key]}</h3><p>${t.policyDescriptions[key]}</p></div><span class="status-label ${i>1?'draft-status':''}">${i<2?s.current:s.draft}</span>${icon('arrow')}`,'policy-row')).join('')}</div></div></section>`;}
function contactPage(){const t=data(),c=t.contact;return intro(c.title,c.intro,c.eyebrow)+`<section class="page-body"><div class="wrap contact-layout"><div><article class="contact-choice">${icon('help')}<h2>${c.supportTitle}</h2><p>${c.supportText}</p>${link('help',c.supportAction+icon('arrow'),'text-link')}<p><a class="text-link" href="mailto:${escape(LINKS.email)}">${escape(LINKS.email)}${icon('mail')}</a></p></article><article class="contact-choice">${icon('people')}<h2>${c.businessTitle}</h2><p>${c.businessText}</p></article></div><div class="form-panel"><h2>${c.formTitle}</h2><p>${c.formIntro}</p><div id="form-result" role="status" aria-live="polite"></div><form id="contact-form"><div class="form-grid"><label class="field"><span>${c.name} *</span><input name="name" autocomplete="name" required maxlength="100"></label><label class="field"><span>${c.email} *</span><input name="email" type="email" autocomplete="email" required maxlength="200"></label></div><label class="field"><span>${c.topic}</span><select name="topic">${c.topics.map((topic,i)=>`<option value="${i}">${topic}</option>`).join('')}</select></label><label class="field"><span>${c.message} *</span><textarea name="message" required minlength="10" maxlength="2000" placeholder="${escape(c.placeholder)}"></textarea></label><label class="form-disclaimer"><input name="consent" type="checkbox" required><span>${c.consent} ${link('policy/privacy',data().footer.privacy)}</span></label><button type="submit" class="button">${c.submit}${icon('arrow')}</button></form></div></div></section>`;}
function policyPage(key){const t=data(),p=t.policy;const current=['terms','privacy'].includes(key);const title=t.footer[key]||t.footer.terms;const body=current?`<p class="note">${p.sourceNote}</p><article class="legal-article" lang="en">${POLICIES[key]}</article><p class="draft-link">${external(LINKS[key],p.official+icon('arrow'),'text-link')}</p>`:`<p class="note">${p.draftNote}</p><h2 class="outline-heading">${p.outline}</h2><div class="outline-sections">${(OUTLINES[key]?.[lang]||OUTLINES[key]?.en||[]).map(([heading,text],i)=>`<section><h2>0${i+1}. ${heading}</h2><p>${text}</p></section>`).join('')}</div>${key==='cookies'?`<p class="draft-link"><button class="button secondary" data-action="cookies">${t.footer.settings}${icon('cookie')}</button></p>`:''}`;return intro(title,t.policyDescriptions[key],current?p.source:p.draftLabel)+`<section class="page-body"><div class="wrap policy-layout"><nav class="policy-nav" aria-label="Policies">${policyKeys.map(k=>link(k==='law'?'law-enforcement':'policy/'+k,t.footer[k],key===k?'active':'')).join('')}</nav><div>${body}<p style="margin-top:40px">${link('safety',p.back+icon('arrow'),'text-link')}</p></div></div></section>`;}
function render(){
  setMobileMenu(false);
  clearHomeAdvance();homeVideoLapComplete=false;
  disposeHeroVideo();
  clearTimeout(loopTimer);loopTimer=null;
  const previous=activePage;
  const parts=(location.hash.replace(/^#\/?/,'')||'home').split('?');
  let route=parts[0];const section=new URLSearchParams(parts[1]||'').get('section');
  if(!['home','about','help','contact','safety','law-enforcement',...policyKeys.filter(x=>x!=='law').map(x=>'policy/'+x)].includes(route))route='home';
  activePage=route;document.body.classList.toggle('home-mode',route==='home');document.body.classList.remove('motion-ready');
  if(route==='home'&&section&&slideIds.includes(section))homeSlide=slideIds.indexOf(section);else if(route==='home'&&previous!=='home')homeSlide=0;
  document.documentElement.lang=lang==='zh'?'zh-CN':lang;
  document.title=(route==='home'?'Bangbo — '+(lang==='zh'?'相遇，让快乐多一点':lang==='hi'?'मिलें, लाइव आएँ और दोस्त बनाएँ':'Party, live stream and make friends'):(data().nav[route]||data().footer[route.split('/')[1]]||data().footer.law)+' — Bangbo');
  renderHeader();renderFooter();
  $('#main-content').innerHTML=route==='home'?homePage():route==='about'?aboutPage():route==='help'?helpPage():route==='contact'?contactPage():route==='safety'?safetyPage():policyPage(route==='law-enforcement'?'law':route.split('/')[1]);
  if(route==='help')renderFaq();if(route==='home'){setHomeSlide(homeSlide);playOpening();}observeHomeLayout();
  if(observer)observer.disconnect();
  if(route!=='home'&&'IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
    document.body.classList.add('motion-ready');
    observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});
    $$('.reveal').forEach(el=>observer.observe(el));
  }
  requestAnimationFrame(()=>{
    if(route==='home'){if(section==='download')showDownload();}
    else if(section&&$('#'+CSS.escape(section)))$('#'+CSS.escape(section)).scrollIntoView({behavior:'auto',block:'start'});
    else window.scrollTo({top:0,behavior:'auto'});
    if(previous&&previous!==route)$('#main-content').focus({preventScroll:true});
  });
}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function closeDialog(){$$('[data-action=more-downloads]').forEach(button=>button.setAttribute('aria-expanded','false'));const root=$('#dialog-root');root.innerHTML='';document.body.style.overflow='';if(lastDialogFocus?.isConnected)lastDialogFocus.focus({preventScroll:true});scheduleHomeAdvance();}
function openDialog(inner,drawer=false){clearHomeAdvance();lastDialogFocus=document.activeElement;$('#dialog-root').innerHTML=`<div class="dialog-backdrop" data-action="backdrop"><section class="${drawer?'review-drawer':'modal-shell'}" role="dialog" aria-modal="true" aria-labelledby="dialog-heading" tabindex="-1">${inner}</section></div>`;document.body.style.overflow='hidden';$('.dialog-backdrop section').focus({preventScroll:true});}
function closeButton(){return `<button class="close-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button>`;}
function showCookies(){const c=data().cookie;let saved={};try{saved=JSON.parse(storage.get('bangbo-preview-cookies')||'{}');}catch{}openDialog(`<div class="dialog-title"><h2 id="dialog-heading">${c.title}</h2>${closeButton()}</div><p>${c.intro}</p><div class="cookie-option"><div><strong>${c.essential}</strong><p>${c.essentialText}</p></div><small>${c.always}</small></div><label class="cookie-option"><div><strong>${c.analytics}</strong><p>${c.analyticsText}</p></div><input id="analytics-choice" type="checkbox" ${saved.analytics?'checked':''}></label><p class="modal-note">${c.note}</p><div class="modal-actions"><button class="button secondary" data-action="cookie-reject">${c.reject}</button><button class="button" data-action="cookie-save">${c.save}</button></div>`);}
document.addEventListener('change',event=>{if(event.target.id==='language'){lang=event.target.value;storage.set('bangbo-preview-language',lang);render();}});
document.addEventListener('input',event=>{if(event.target.id==='faq-search'){searchQuery=event.target.value;renderFaq();}});
document.addEventListener('click',event=>{
 const anchor=event.target.closest('a[href]');if(anchor?.getAttribute('href')==='#/home?section=download'){event.preventDefault();setMobileMenu(false);showDownload();return;}
 const dot=event.target.closest('[data-slide]');if(dot){setHomeSlide(Number(dot.dataset.slide));return;}
 if(activePage==='home'&&anchor?.getAttribute('href')==='#/home'){event.preventDefault();setHomeSlide(0);setMobileMenu(false);scheduleHomeAdvance();return;}

 if(event.target.closest('.skip-link')){event.preventDefault();$('#main-content').focus();$('#main-content').scrollIntoView({block:'start'});return;}
 const category=event.target.closest('[data-category]');if(category){helpCategory=category.dataset.category;$$('[data-category]').forEach(el=>{el.classList.toggle('active',el===category);el.setAttribute('aria-pressed',String(el===category));});renderFaq();return;}
 if(event.target.closest('#menu-toggle')){setMobileMenu(!$('#mobile-nav').classList.contains('open'));return;}
 const action=event.target.closest('[data-action]')?.dataset.action;
 if(action==='start-hero-video'){heroUserStarted=true;syncHeroVideo();return;}
 if(action==='more-downloads'){showMoreDownloads(event.target.closest('[data-action=more-downloads]'));return;}
 if(action==='preview-download'){const url=LINKS[event.target.closest('[data-channel]').dataset.channel];if(url)window.open(url,'_blank','noopener,noreferrer');else toast(BANGBO_COPY[lang].pending);return;}
 if(action==='close-dialog'||(action==='backdrop'&&event.target.classList.contains('dialog-backdrop'))){closeDialog();return;}
 if(action==='cookies'){showCookies();return;}
 if(action==='cookie-save'||action==='cookie-reject'){storage.set('bangbo-preview-cookies',JSON.stringify({analytics:action==='cookie-save'&&$('#analytics-choice').checked,updatedAt:new Date().toISOString()}));closeDialog();toast(data().cookie.saved);return;}
 if(event.target.closest('#form-again')){render();return;}
 if(event.target.closest('#mobile-nav a'))setMobileMenu(false);
});
document.addEventListener('submit',event=>{if(event.target.id!=='contact-form')return;event.preventDefault();if(!event.target.checkValidity()){event.target.reportValidity();return;}$('#form-result').innerHTML=`<div class="form-result">${data().contact.success}</div><button class="text-link" id="form-again">${data().contact.again}${icon('arrow')}</button>`;event.target.hidden=true;$('#form-result').scrollIntoView({block:'center',behavior:'smooth'});});
document.addEventListener('keydown',event=>{if(!$('#dialog-root').firstElementChild){if(event.key==='Escape'&&$('#mobile-nav')?.classList.contains('open')){setMobileMenu(false);$('#menu-toggle').focus();}return;}if(event.key==='Escape'){event.preventDefault();closeDialog();return;}if(event.key==='Tab'){const list=$$('a[href],button,input,select,textarea,[tabindex="0"]',$('#dialog-root')).filter(el=>!el.disabled);if(!list.length)return;const first=list[0],last=list.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement=== $('.dialog-backdrop section'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
function canNavigate(){return activePage==='home'&&!$('#dialog-root').firstElementChild&&!$('#mobile-nav')?.classList.contains('open');}
function needsInnerScroll(target,direction){const slide=target.closest?.('.home-slide');return !!slide&&slide.scrollHeight>slide.clientHeight+2&&(direction>0?slide.scrollTop+slide.clientHeight<slide.scrollHeight-2:slide.scrollTop>2);}
document.addEventListener('wheel',event=>{
 if(!canNavigate()||!event.target.closest('.home-stage')||event.ctrlKey||window.visualViewport?.scale>1.01)return;
 if(window.innerWidth<=680||needsInnerScroll(event.target,Math.sign(event.deltaY)))return;
 event.preventDefault();if(wheelQuiet)return;wheelAmount+=event.deltaMode===1?event.deltaY*16:event.deltaY;if(Math.abs(wheelAmount)<35)return;moveSlide(Math.sign(wheelAmount));wheelAmount=0;wheelQuiet=1;
},{passive:false});
let wheelTimer;document.addEventListener('wheel',()=>{clearTimeout(wheelTimer);wheelTimer=setTimeout(()=>{wheelQuiet=0;wheelAmount=0;},200);},{passive:true});
document.addEventListener('keydown',event=>{if(!canNavigate()||event.target.closest?.('input,select,textarea,button,a')||window.visualViewport?.scale>1.01)return;const keys=window.innerWidth<=680?['ArrowLeft','ArrowRight']:['ArrowUp','ArrowDown'];if([keys[0],keys[1],'PageDown','PageUp','Home','End'].includes(event.key)){if(needsInnerScroll(event.target,event.key===keys[0]||event.key==='PageUp'?-1:1)&&!['Home','End'].includes(event.key))return;event.preventDefault();if(event.key==='Home')setHomeSlide(0);else if(event.key==='End')setHomeSlide(screenTotal-1);else moveSlide(event.key===keys[0]||event.key==='PageUp'?-1:1);}});
document.addEventListener('touchstart',event=>{
 touchStart=null;if(!canNavigate()||!event.target.closest('.home-stage')||event.target.closest('button,a,input,select,textarea'))return;
 if(event.touches.length!==1||window.visualViewport?.scale>1.01)return;
 const point=event.touches[0];if(point.clientX<28||point.clientX>window.innerWidth-28)return;
 touchStart={x:point.clientX,y:point.clientY,cancelled:false};
},{passive:true});
document.addEventListener('touchmove',event=>{
 if(!touchStart)return;if(event.touches.length!==1||window.visualViewport?.scale>1.01){touchStart=null;return;}
 const dx=touchStart.x-event.touches[0].clientX,dy=touchStart.y-event.touches[0].clientY;
 if(window.innerWidth<=680&&Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx))touchStart.cancelled=true;
},{passive:true});
document.addEventListener('touchend',event=>{
 if(!touchStart)return;const start=touchStart;touchStart=null;if(start.cancelled||!canNavigate()||!event.changedTouches.length||window.visualViewport?.scale>1.01)return;
 const dx=start.x-event.changedTouches[0].clientX,dy=start.y-event.changedTouches[0].clientY;
 if(window.innerWidth<=680){if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.4)moveSlide(Math.sign(dx));}
 else if(Math.abs(dy)>50&&Math.abs(dy)>Math.abs(dx)*1.4&&!needsInnerScroll(event.target,Math.sign(dy)))moveSlide(Math.sign(dy));
},{passive:true});
document.addEventListener('touchcancel',()=>{touchStart=null;},{passive:true});
window.addEventListener('resize',()=>{if(window.innerWidth>680)setMobileMenu(false);if(activePage==='home')setHomeSlide(homeSlide);});
document.addEventListener('visibilitychange',()=>{syncHeroVideo();scheduleHomeAdvance();});
document.addEventListener('touchstart',event=>{if(event.target.closest?.('.home-stage'))clearHomeAdvance();},{passive:true});
document.addEventListener('touchend',scheduleHomeAdvance,{passive:true});
document.addEventListener('touchcancel',scheduleHomeAdvance,{passive:true});
window.visualViewport?.addEventListener('resize',scheduleHomeAdvance);
window.addEventListener('hashchange',()=>{closeDialog();render();});
